"""C spelling helpers shared by the C emitters.

The emitters write code already in the repository's clang-format style
(`.clang-format`: LLVM base, 4-space indent, 100 columns, parameters packed
and aligned after the open parenthesis), so the formatter hook never rewrites a
generated file and the drift check stays byte-exact.
"""

from __future__ import annotations

import textwrap

from . import typesys
from .model import Api, Callback, Deprecation, Field, Function, Param, version_text

COLUMNS = 100
BANNER = (
    "GENERATED by scripts/codegen/vmafx-api.py from core/api/vmafx.toml (ADR-1852).\n"
    "Do not edit: change the definition and run `python3 scripts/codegen/vmafx-api.py --write`."
)
NULLPTR_BEGIN = (
    "/* NOLINTBEGIN(modernize-use-nullptr): C translation unit. The fork builds C as\n"
    " * C23, where clang-tidy also proposes the `nullptr` keyword, but MSVC's\n"
    " * documented /std:clatest C23 feature set does not include `nullptr` and the\n"
    " * required Windows builds compile this TU with cl.exe (C2065). ADR-1138. */"
)
NULLPTR_END = "/* NOLINTEND(modernize-use-nullptr) */"


def licence_block() -> str:
    # The tag is split so licence scanners do not read this literal as a header.
    tag = "SPDX-" + "License-Identifier"
    return f"/**\n *\n *  Copyright 2026 Lusoris\n *\n * {tag}: EUPL-1.2\n */\n"


def banner_comment() -> str:
    lines = BANNER.split("\n")
    body = "\n".join(" * " + line for line in lines)
    return "/*\n" + body + "\n */\n"


def doc_block(text: str, indent: str = "", extra: tuple[str, ...] = ()) -> str:
    """A `/** ... */` block wrapped to the column limit."""
    width = COLUMNS - len(indent) - 3
    lines = textwrap.wrap(text, width=width) if text else []
    lines += list(extra)
    if len(lines) == 1 and len(indent) + len(lines[0]) + 7 <= COLUMNS:
        return f"{indent}/** {lines[0]} */\n"
    body = "".join(f"{indent} * {line}\n".replace(" * \n", " *\n") for line in lines)
    return f"{indent}/**\n{body}{indent} */\n"


def field_decl(api: Api, fld: Field) -> str:
    """`uint32_t name;`, `VmafxFence acquire;`, `const VmafxModel *model;`, `VmafxPlane plane[3];`."""
    base = typesys.base_spelling(fld.type)
    if typesys.kind(api, fld.type) == "handle":
        base = ("const " if fld.const else "") + base + " *"
    suffix = f"[{fld.count}]" if fld.count else ""
    return typesys.pointer_join(base, fld.name) + suffix + ";"


# Spelling of a parameter per pass mode; `{t}` is the value type.
MODE_SPELLING = {
    "error": "VmafxError **",
    "out_handle": "{t} **",
    "out": "{t} *",
    "in_const": "const {t} *",
}


def param_decl(api: Api, param: Param) -> str:
    base = typesys.base_spelling(param.type)
    if param.mode in MODE_SPELLING:
        # `const char *` + ` *` -> `const char **` (an `out` string).
        return MODE_SPELLING[param.mode].format(t=base).replace("* *", "**") + param.name
    kind = typesys.kind(api, param.type)
    if kind == "struct":
        return f"const {base} *{param.name}"
    if kind in ("handle", "foreign"):
        return f"{base} *{param.name}"
    return typesys.pointer_join(base, param.name)


def return_spelling(api: Api, returns: str) -> str:
    if returns == "void":
        return "void"
    if returns.startswith(("handle:", "foreign:")):
        return returns.split(":", 1)[1] + " *"
    return typesys.base_spelling(returns)


def packed(head: str, items: list[str], tail: str) -> str:
    """`head(item, item, ...)tail`, bin-packed and aligned after the parenthesis."""
    single = head + "(" + ", ".join(items) + ")" + tail
    if len(single) <= COLUMNS or not items:
        return single
    indent = " " * (len(head) + 1)
    lines: list[str] = []
    current = head + "("
    for position, item in enumerate(items):
        last = position == len(items) - 1
        piece = item + (")" + tail if last else ",")
        candidate = current + ("" if current.endswith("(") else " ") + piece
        if len(candidate) <= COLUMNS or current.endswith("("):
            current = candidate
            continue
        lines.append(current)
        current = indent + piece
    lines.append(current)
    return "\n".join(lines)


def _fits(text: str) -> bool:
    return all(len(line) <= COLUMNS for line in text.split("\n"))


def assignment(lhs: str, callee: str, args: list[str]) -> str:
    """`lhs = callee(args);` as clang-format breaks it: after `=` when the call then fits
    on one line, else after `=` with the arguments packed after the parenthesis."""
    single = f"{lhs} = {callee}(" + ", ".join(args) + ");"
    if len(single) <= COLUMNS:
        return single
    indent = " " * (len(lhs) - len(lhs.lstrip()) + 4)
    rest = f"{indent}{callee}(" + ", ".join(args) + ");"
    if len(rest) <= COLUMNS:
        return f"{lhs} =\n{rest}"
    broken = f"{lhs} =\n" + packed(f"{indent}{callee}", args, ";")
    kept = packed(f"{lhs} = {callee}", args, ";")
    # clang-format's penalties pick the shorter form; on a tie, the break after `=`.
    if _fits(broken) and broken.count("\n") <= kept.count("\n"):
        return broken
    return kept


def object_macro(name: str, value: str) -> str:
    """`#define name value`, continued on the next line past the column limit."""
    line = f"#define {name} {value}"
    if len(line) <= COLUMNS:
        return line + "\n"
    head = f"#define {name}"
    return head + " " * (COLUMNS - 1 - len(head)) + "\\\n    " + value + "\n"


def deprecation_note(dep: Deprecation) -> str:
    since, removal = version_text(dep.since), version_text(dep.removal)
    return f"since {since}; use {dep.replacement}; removal in {removal}"


def declaration(api: Api, fn: Function, export: str) -> str:
    ret = return_spelling(api, fn.returns)
    head = typesys.pointer_join(f"{export} {ret}", fn.name)
    params = [param_decl(api, p) for p in fn.params] or ["void"]
    text = packed(head, params, ";")
    if fn.deprecated is None:
        return text
    return f'VMAFX_DEPRECATED("{deprecation_note(fn.deprecated)}")\n' + text


def callback_typedef(api: Api, item: Callback) -> str:
    """`typedef R (*Name)(params);` packed like a declaration."""
    head = f"typedef {return_spelling(api, item.returns)} (*{item.name})"
    head = head.replace("* (*", "*(*")
    return packed(head, [param_decl(api, p) for p in item.params], ";")


pointer_join = typesys.pointer_join
